"""AI 지원(규칙 기반) — 초보자용 자연어 안내 엔진.

LLM이 아니라 결정적 규칙이다: 의도 분류(인사·소개·용어·화면 설명·화면 이동·작업 방법·오류·진행·다음 단계·공식 근거 검색) →
세션 상태/현재 화면을 반영한 답 + 바로가기 버튼 + 이어서 물어볼 질문 칩. 근거가 없으면 지어내지 않고 '확인 필요'로 답한다.
"""
from __future__ import annotations
import re

from . import content as C
from . import guide as G
from . import sysinfo

ROLE_NAV = {"ops": ("admin",), "usage": ("admin",), "rvw": ("reviewer", "instructor", "admin"), "fbq": ("admin",), "vmx": ("reviewer", "instructor", "admin"), "inst": ("reviewer", "instructor", "admin"), "partner": ("reviewer", "instructor", "admin"), "conf": ("reviewer", "instructor", "admin")}


_kb = G._kb


def ask(label, q):
    return {"type": "ai", "label": label, "q": q}


def norm(q):
    q = (q or "").lower()
    q = re.sub(r"[^0-9a-z가-힣_\-\.\s·]", " ", q)
    return re.sub(r"\s+", " ", q).strip()


_JOSA = re.compile(r"(?<=[가-힣a-z0-9])(은|는|이|가|을|를|도|만|에서|에게|으로|로|랑|하고|와|과|의)(?=\s|$)")


def strip_josa(q):
    return _JOSA.sub("", q)


def forms(q):
    s2 = strip_josa(q)
    return [q] if s2 == q else [q, s2]


def has(q, *ws):
    fs = forms(q)
    return any(w in f for w in ws for f in fs)


