CAPS = ["다음에 뭐 해?", "이 화면은 뭐야?", "SQL은 어떻게 실행해?", "Unity Catalog가 뭐야?", "권한 오류는 어떻게 해결해?", "전체 메뉴 구성 알려줘"]


def _can_nav(view, role):
    allowed = ROLE_NAV.get(view)
    return not allowed or role in allowed


def _nav(view, role, label=None):
    return G.nav(label or SCR[view][0], view)


def _screens_in(q):
    """질문에 나온 화면들을 '가장 길게 일치한 표현' 순으로 돌려준다(번호 표기 UI-05 포함)."""
    sc = {}
    fs = forms(q)
    for v, ws in ALIAS.items():
        best = max([len(w) for w in ws for f in fs if w in f] + ([len(SCR[v][0])] if SCR[v][0].lower() in q else []) + [0])
        if best:
            sc[v] = best
    for v in SCR:
        m = re.match(r"ui-(\d+[a-z]?)", SCR[v][0].lower())
        if m and re.search(rf"\bui[- ]?{m.group(1)}(?![0-9a-z])", q):
            sc[v] = max(sc.get(v, 0), 100)
    return [v for v, _ in sorted(sc.items(), key=lambda x: -x[1])]


def _screen_answer(v, role, here=False):
    name, why, steps, nxt, tip = SCR[v]
    allowed = ROLE_NAV.get(v)
    t = f"**{name}**\n\n{why}\n\n**처음 할 일**\n" + "\n".join(f"{i}. {s}" for i, s in enumerate(steps, 1)) + f"\n\n💡 {tip}"
    if allowed and role not in allowed:
        t += f"\n\n(이 화면은 {'/'.join(allowed)} 전용이라 현재 역할로는 열 수 없습니다.)"
    sc = [] if (here or not _can_nav(v, role)) else [_nav(v, role, f"{name} 열기")]
    if nxt and _can_nav(nxt, role):
        sc.append(_nav(nxt, role, f"다음 화면: {SCR[nxt][0]}"))
    return t, sc


def _match_how(q):
    best, score = None, 0
    fs = forms(q)
    for keys, title, steps, navs in HOW:
        s = max((len(k) for k in keys for f in fs if k in f), default=0)
        if s > score:
            best, score = (title, steps, navs), s
    return best


def _gloss(q):
    fs = [f" {x} " for x in forms(q)]
    best, score = None, 0
    for names, title, text, view in GLOSS:
        s = max((len(n.strip()) for n in names for qq in fs if n in qq), default=0)
        if s > score:
            best, score = (title, text, view), s
    return best


def _err_code(message):
    m = re.search(r"(?<![A-Za-z_])([A-Z][A-Z_]{4,})(?![A-Za-z_])", message or "")
    return m.group(1) if m and m.group(1) in G.ERR_HELP else None


def _suggest(view, role):
    """현재 화면에서 이어서 물어볼 만한 질문 칩."""
    out = [ask("이 화면은 뭐야?", "이 화면은 뭐야?"), ask("다음에 뭐 해?", "다음에 뭐 해?")]
    if view in ("sql", "comp", "perm", "cat"):
        out.append(ask("권한 오류 해결법", "권한 오류는 어떻게 해결해?"))
    out.append(ask("용어가 어려워요", "Unity Catalog가 뭐야?"))
    return out[:4]


def answer(S, actor, message, mode_real=False, view=None):
    q = norm(message)
    role = (actor or {}).get("role", "learner")
    view = view if view in SCR else None
    sc, intent = [], "fallback"

    def out(text, shortcuts=None, intent_=None, sug=True):
        s = list(shortcuts or [])
        if sug:
            s += [x for x in _suggest(view, role) if x["q"] != message][:3]
        ctx = None
        if S is not None:
            J = G.journey(S)
            ctx = {"percent": J["percent"], "next": J["next"] and {"step_no": J["next"]["step_no"], "title": J["next"]["title"]}}
        return {"answer": text, "shortcuts": s, "context": ctx, "intent": intent_ or intent, "view": view}

    if not q:
        return out("질문을 입력해 주세요. 예: '다음에 뭐 해?', '이 화면은 뭐야?'", intent_="empty")
    # 1) 인사·도움
    if re.fullmatch(r"(안녕\S*|하이|hello|hi|ㅎㅇ|반가\S*|고마\S*|감사\S*|땡큐|thanks?)( .*)?", q) and len(q) < 20:
        return out("안녕하세요! 저는 **AI 지원**입니다(AI 모델이 아니라 정해진 규칙과 검증된 자료로 안내합니다). 지금 할 일, 화면 설명, 용어, 오류 해결을 도와드려요. 아래 질문부터 눌러 보세요.", [ask(x, x) for x in CAPS[:4]], "greeting", sug=False)
    if has(q, "뭘 할 수", "무엇을 할 수", "뭐 할 수", "뭘 물어", "어떻게 물어", "사용법", "도움말", "할 줄 아", "무슨 질문", "물어볼 수") and not has(q, "sql", "화면은") and not _screens_in(q):
        return out("이런 걸 물어보세요:\n- 지금 할 일: '다음에 뭐 해?', '진행률'\n- 화면: '이 화면은 뭐야?', '권한 화면 열어줘'\n- 용어: 'Unity Catalog가 뭐야?', '메달리온이 뭐야?'\n- 방법: 'SQL은 어떻게 실행해?', '세션은 어떻게 지워?'\n- 오류: '왜 실패했어?', '권한 오류는 어떻게 해결해?'\n- 앱: '업데이트는 어떻게 해?', '피드백은 어디서 보내?'\n- AX: '자동 구축하는 방법', '온톨로지가 뭐야?', '제안 승인 실행 방법', '문서 올려 검색하는 방법', '지원하는 DB 알려줘'\n- 서버 자원(관리자): '서버 자원 확인하는 법', '메모리 부족하면 어떻게 해?'", [ask(x, x) for x in CAPS], "capabilities", sug=False)
    if q in ("시작", "시작해", "시작할래", "시작하자", "처음", "처음이야", "처음이에요", "도와줘", "도와주세요", "help"):
        t0 = HOW[0]
        return out(f"**{t0[1]}**\n\n" + "\n".join(t0[2]), [G.nav(l, v) for l, v in t0[3]], "howto")
    # 2) 오류 코드 직접 언급
    code = _err_code(message)
    if code and not has(q, "화면", "열어"):
        text = f"**{code}**\n\n{G.ERR_HELP[code]}"
        if code == "WAREHOUSE_NOT_RUNNING":
            sc.append(G.run("Warehouse 시작", "warehouse", {"action": "start"}, "comp"))
            sc.append(G.nav("Compute 화면으로 이동", "comp"))
        if code in ("INSUFFICIENT_PERMISSIONS",):
            sc.append(G.nav("권한 요청하러 가기", "perm"))
        return out(text, sc, "error_code")
    # 3) 현재 화면/위치
    if has(q, "이 화면", "여기는", "여기가", "지금 화면", "현재 화면", "이 페이지", "이 메뉴", "지금 어디", "여기 어디", "여긴 어디", "내가 어디", "어디에 있", "무슨 화면", "이 창") and not has(q, "다음 화면", "이전 화면", "어디까지", "어디서부터"):
        if view:
            t, s = _screen_answer(view, role, here=True)
            n = None
            if S is not None:
                J = G.journey(S)
                n = J["next"]
                if n and not mode_real:
                    s.insert(0, n["shortcut"])
                    t += f"\n\n📍 지금 단계: **{n['step_no']}단계 · {n['title']}**"
            return out(f"지금 보고 계신 화면은 {t}", s, "this_screen")
        return out("현재 화면을 알 수 없습니다. 위쪽 메뉴에서 화면을 고르거나, 알고 싶은 화면 이름을 말해 주세요(예: 'SQL Editor가 뭐야?').", [], "this_screen")
    # 4) 전체 절차·진행·다음
    if has(q, "전체 절차", "전체 단계", "로드맵", "단계 목록", "절차 보여", "전체 흐름", "순서가 어떻게", "전체 순서"):
        if S is None:
            return out("전체 절차를 보려면 먼저 세션을 시작해야 합니다. 환경 점검에서 세션을 만드세요.", [G.nav("환경 점검으로 이동", "env")], "journey")
        J = G.journey(S)
        t = "전체 절차입니다(순서는 권장, 건너뛸 수 있음).\n" + "\n".join(f"{s['no']}. {s['title']} — {s['done']}/{s['total']}" + (" ✅" if s["status"] == "done" else "") for s in J["steps"])
        return out(t, [G.nav("현재 단계로 이동", J["steps"][J["current"]]["view"])] if J["current"] is not None else [], "journey")
    if has(q, "진행률", "진행 상황", "진행 현황", "얼마나 했", "몇 %", "완료율", "어디까지", "몇 단계"):
        if S is None:
            return out("진행률은 세션을 시작한 뒤부터 계산됩니다.", [G.nav("환경 점검으로 이동", "env")], "progress")
        J = G.journey(S)
        return out(f"전체 진행률 **{J['percent']}%** ({J['done']}/{J['total']} 항목). " + (f"지금은 {J['next']['step_no']}단계 ‘{J['next']['title']}’ 입니다." if J["next"] else "모든 항목을 마쳤습니다."), [J["next"]["shortcut"]] if J["next"] and not mode_real else [], "progress")
    if has(q, "다음에", "다음 뭐", "다음엔", "다음은", "다음 단계", "next", "이제 뭐", "이제 뭘", "뭐 해야", "뭘 해야", "뭐부터", "뭘부터", "어디서부터", "무엇을 해야", "뭐 하면", "뭘 하면", "계속 진행", "계속 해야", "이어서 해야") and not has(q, "다음 화면", "공부", "시험 준비"):
        if S is None:
            return out("먼저 세션을 시작해야 단계를 안내할 수 있습니다. **환경 점검(UI-01)**에서 [세션 시작]을 누르세요.", [G.nav("환경 점검으로 이동", "env")], "next")
        J = G.journey(S)
        if mode_real:
            return out("실전형에서는 정답 위치를 안내하지 않습니다. 현재 단계는 **" + (J["next"]["title"] if J["next"] else "완료") + "** 입니다.", [G.nav("전체 절차 보기", "env")], "next")
        t, s = G._next_answer(S, J)
        n = J["next"]
        if n and view and n["shortcut"].get("view") and n["shortcut"]["view"] != view and n["shortcut"].get("type") == "nav":
            t += f"\n\n📍 지금은 **{SCR[view][0]}** 화면이고, 이 단계는 **{SCR[n['shortcut']['view']][0]}** 화면에서 합니다. 버튼을 누르면 이동합니다." if n["shortcut"]["view"] in SCR else ""
        return out(t, s, "next")
    # 4b) 구체적인 '방법' 질문은 오류 분기보다 먼저 (예: 'Job 실패했을 때 어떻게 해?')
    hw = _match_how(q)
    if hw and (hw[0] in DIRECT or (has(q, "어떻게", "방법", "하려면", "해결", "대처", "하는 법", "하나요", "팁", "고치") and not has(q, "왜 "))):
        return out(f"**{hw[0]}**\n\n" + "\n".join(hw[1]), [G.nav(l, v) for l, v in hw[2] if _can_nav(v, role)], "howto")
    # 4c) 버전 질문은 실제 값으로 답한다
    if has(q, "버전 몇", "버전이 몇", "현재 버전", "버전 알려", "몇 버전", "버전은 뭐", "어떤 버전"):
        return out(f"현재 서버 버전은 **v{sysinfo.VERSION}** 입니다(정식 서비스 전이라 0.y.z 표기). 자세한 정보와 변경 이력은 위쪽 메뉴 **도움말 > 시스템 정보**(Alt+Shift+I)에서 볼 수 있고, 새 버전이 있으면 업데이트 알림이 뜹니다.", [], "version")
    g0 = _gloss(q)
    if g0 and has(q, "왜 중요", "왜 필요", "왜 써", "왜 쓰", "왜 이렇게", "중요해", "필요해") and not has(q, "오류", "에러", "실패", "안 되", "안되"):
        return out(f"**{g0[0]}**\n\n{g0[1]}\n\n※ 정확한 공식 정의는 Databricks 문서에서 확인하세요.", [_nav(g0[2], role, f"관련 화면: {SCR[g0[2]][0]}")] if g0[2] and _can_nav(g0[2], role) else [], "glossary")
    # 5) 오류·실패
    if has(q, "오류", "에러", "실패", "안돼", "안 돼", "안되", "안 되", "왜 ", "error", "failed", "막혔", "막혀", "문제가 ", "이상해", "작동", "동작이 안", "먹통") and not has(q, "권한 오류는 어떻게", "권한 요청"):
        if S is None:
            return out("세션이 없어 최근 실행 기록은 볼 수 없지만, SQL이 안 될 때 가장 흔한 원인은 이 순서입니다.\n1. **Warehouse가 꺼져 있음** — Compute에서 시작\n2. **권한 부족** — 오류 코드가 INSUFFICIENT_PERMISSIONS면 권한 요청\n3. **이름 철자/3단계 이름** — catalog.schema.table\n\n세션을 시작하면 실패한 이력을 직접 분석해 해결 단계를 안내해 드립니다. 앱이 안 열리거나 접속이 안 되는 문제라면 '접속이 안 돼요'라고 물어보세요.", [G.nav("환경 점검으로 이동", "env"), G.nav("Compute로 이동", "comp"), G.nav("권한 화면으로 이동", "perm")], "error")
        f = G._last_failure(S)
        if not f:
            return out("최근 실패·차단 이벤트가 없습니다. 오류가 나면 SQL 실행 이력의 failed(또는 하단 로그의 [해결 방법 보기])를 눌러 보세요.", [], "error")
        code2 = f["detail"].get("code") or ""
        t = f"최근 이벤트: **{f['event_type']}** ({f['outcome']})" + (f" · `{code2}`" if code2 else "") + "\n\n" + G.ERR_HELP.get(code2, "로그의 error code와 메시지를 먼저 읽고, 어느 계층(권한/데이터/코드/배포/승인)의 문제인지 좁혀 보세요.")
        if f["detail"].get("missing"):
            m = f["detail"]["missing"]
            t += f"\n\n누락 권한: **{m['privilege']}** on `{m['securable']}`"
            sc.append(G.nav("이 권한 요청서 열기(자동 입력)", "perm", prefill={"t_sec": m["securable"], "t_priv": m["privilege"], "t_reason": f"{m['securable']} 조회 업무 — {m['privilege']} 최소권한 요청"}))
        if code2 == "WAREHOUSE_NOT_RUNNING":
            sc.append(G.run("Warehouse 시작", "warehouse", {"action": "start"}, "comp"))
        t += "\n\n💡 같은 내용을 SQL Editor 실행 이력의 failed를 눌러도 단계별로 볼 수 있어요."
        return out(t, sc, "error")
    # 6) 화면 이동/설명 요청
    qm = "?" in (message or "") or "？" in (message or "")
    scr = _screens_in(q)
    nav_words = has(q, "어디", "열어", "이동", "가줘", "가고", "가자", "바로", "보여", "찾아", "가려면", "화면으로", "메뉴가", "메뉴 어디")
    exp_words = has(q, "뭐야", "뭔가", "뭐예요", "무엇", "설명", "무슨", "어떤", "뭘 하", "뭐하", "뭐 하는", "하는 사람", "어떤 사람", "기능", "용도", "알려", "란 ", "이란", "역할", "뭐에요", "화면이 뭐", "에 대해")
    howto = _match_how(q)
    # 6a) 작업 방법(FAQ)이 더 구체적이면 우선
    if howto and (has(q, "어떻게", "방법", "하려면", "보려면", "풀려면", "하는 법", "켜는 법", "쓰는 법", "하는법", "하고 싶", "팁", "준비", "어디서", "해야", "하나요", "할까", "가능", "되나", "돼요", "시작", "설치", "삭제", "지우", "요청", "제출", "확인", "해결", "알려", "처음", "단축키", "메뉴", "느려", "저장") or qm) and not (scr and nav_words and not has(q, "어떻게")) and not (exp_words and (scr or _gloss(q)) and not has(q, "어떻게", "방법", "하려면")):
        title, steps, navs = howto
        s = [G.nav(l, v) for l, v in navs if _can_nav(v, role)]
        return out(f"**{title}**\n\n" + "\n".join(steps), s, "howto")
    if scr and nav_words and not exp_words:
        names = [v for v in scr if _can_nav(v, role)][:3]
        if not names:
            return out(f"**{SCR[scr[0]][0]}** 은(는) {'/'.join(ROLE_NAV[scr[0]])} 전용 화면이라 현재 역할로는 열 수 없습니다.", [], "navigate")
        return out("바로 이동할 수 있어요. 버튼을 눌러 보세요.", [_nav(v, role, f"{SCR[v][0]} 열기") for v in names], "navigate", sug=False)
    g = _gloss(q)
    if g and (has(q, "뭐야", "뭔가", "뭐예요", "뭐에요", "무엇", "뜻", "의미", "설명", "이란", "란 ", "차이", "개념", "알려", "뭐지", "모르겠", "이해", "어려워", "뭐 하는", "뭐하는", "하는 사람", "어떤 사람", "어떻게", "방법", "하는 법", "사용법", "지원", "가능", "되나", "경로", "만들", "쓰는", "설정") or len(q) <= 30) and not (scr and has(q, "화면") and not has(q, "뭐야")):
        title, text, gv = g
        s = [_nav(gv, role, f"관련 화면: {SCR[gv][0]}")] if gv and _can_nav(gv, role) else []
        hit = _kb(message)
        extra = ("\n\n" + "\n".join(f"📚 {k['title']} — 근거: {k['url']} (확인일 {C.BASIS})" for k in hit[:1])) if hit else ""
        return out(f"**{title}**\n\n{text}{extra}\n\n※ 정확한 공식 정의는 Databricks 문서에서 확인하세요.", s, "glossary")
    if scr and (exp_words or True):
        v = scr[0]
        t, s = _screen_answer(v, role)
        return out(t, s, "screen")
    if howto:
        title, steps, navs = howto
        return out(f"**{title}**\n\n" + "\n".join(steps), [G.nav(l, v) for l, v in navs if _can_nav(v, role)], "howto")
    # 7) 공식 근거 검색(KB)
    hit = _kb(message)
    if hit:
        t = "\n\n".join(f"**{k['title']}** — {k['text']}" for k in hit[:2]) + "\n\n" + "\n".join(f"근거: {k['url']} (확인일 {C.BASIS})" for k in hit[:2])
        return out(t, [S and G.journey(S)["next"] and not mode_real and G.journey(S)["next"]["shortcut"]] if False else [], "kb")
    # 8) 모르는 질문 — 지어내지 않고 가까운 화면·질문을 제안
    near = _screens_in(q)[:3]
    t = ("승인된 근거에서 정확한 답을 찾지 못했습니다 — **확인 필요**로 두고 임의로 확정하지 않겠습니다.\n\n"
         "이렇게 물어보시면 잘 답해 드려요: ‘다음에 뭐 해?’, ‘이 화면은 뭐야?’, ‘왜 실패했어?’, ‘Unity Catalog가 뭐야?’, ‘SQL은 어떻게 실행해?’.\n"
         "Databricks 공식 기능에 대한 질문이면 공식 문서를 확인해 주세요. 이 앱에 없는 기능이라면 AXOS 탭에서 요청해 주세요.")
    return out(t, [_nav(v, role, SCR[v][0]) for v in near if _can_nav(v, role)] + [G.nav("전체 메뉴 구성 보기", "env")][:0], "fallback")
